// CSV string'i al
const csvData = $input.first().json.stdout;

// Satırlara ayır
const lines = csvData.trim().split('\n');

// Header'ı parse et
const headers = lines[0].split(',');

// Data satırlarını parse et ve objelere dönüştür
const tableData = lines.slice(1).map(line => {
  const values = line.split(',');
  const row = {};

  headers.forEach((header, index) => {
    row[header] = values[index];
  });

  return row;
});

// Sonucu döndür
return tableData.map(row => ({ json: row }));

// Workflow kontrolü
const workflowType = $('Get Run Ref').first().json.workflow_type;


// Gelen JSON verisini al (artık CSV parse etmiyoruz)
const parsedData = $input.all().map(item => item.json);

let result;

// Lane'leri ayrı tutması gereken tek durum gerçek XP run'ları.
// Boş / Standard / NextSeq / MiSeq vb. hepsinde lane 0'a toplanır.
if (workflowType !== "XP Workflow") {
  // SampleID'ye göre grupla ve reads'leri topla
  const grouped = {};

  parsedData.forEach(item => {
    const sampleId = item['SampleID'];

    if (!grouped[sampleId]) {
      // İlk kez görülen sample - kopyala
      grouped[sampleId] = { ...item };
      grouped[sampleId]['# Reads'] = parseInt(item['# Reads'].replace(/,/g, '')) || 0;
      grouped[sampleId]['Lane'] = '0';  // Lane'i 0 yap
    } else {
      // Zaten var - reads'i ekle
      grouped[sampleId]['# Reads'] += parseInt(item['# Reads'].replace(/,/g, '')) || 0;
    }
  });

  // Objeyi array'e çevir
  result = Object.values(grouped);

} else {
  // XP workflow - lane'leri olduğu gibi bırak
  result = parsedData;
}

return result.map(item => ({ json: item }));

return $input.all().map(item => {
  const stdout = item.json.stdout;
  const lines = stdout.trim().split('\n').filter(l => l.length > 0);

  const lane = item.json.Lane;
  const laneStr = lane && lane !== '0' ? `_L00${lane}_` : null;

  const r1 = laneStr
    ? lines.find(l => l.includes(laneStr) && l.includes('_R1_'))
    : lines.find(l => l.includes('_R1_'));

  const r2 = laneStr
    ? lines.find(l => l.includes(laneStr) && l.includes('_R2_'))
    : lines.find(l => l.includes('_R2_'));

  return {
    json: {
      SampleID: item.json.SampleID,
      Lane: lane,
      r1_path: r1 ? r1.replace('/mnt/smb_share/', '/volume1/ALLDATA/') : null,
      r2_path: r2 ? r2.replace('/mnt/smb_share/', '/volume1/ALLDATA/') : null
    }
  };
});

const readsSettings = $('Get Reads Settings').first().json;
const samples = $('Get Planned Reads').all();
const runId = $('Edit Fields').item.json.run_id;
const instrumentModel = $('Get Run Ref').item.json.instrument_model;

// Illumina i5 orientation taxonomy:
// - Revcomp chemistry (NextSeq 1000/2000, NovaSeq X/X Plus, iSeq, NovaSeq 6000 v1.5 reagent):
//   SampleSheet'e i5'in RC'sini yaz. DRAGEN RunInfo.xml IsReverseComplement="Y" gorur ve
//   demux'ta SS yazimini bir kez daha RC eder -> demux key = forward, raw forward ile match.
// - Forward chemistry (NovaSeq 6000 v1.0 reagent, MiSeq, HiSeq, NextSeq 550):
//   SampleSheet'e i5'i forward (kit dokumantasyonu) yaz.
// Empirik dogrulama: 260508_VH01138_4 (NextSeq 2000) needsRC=true gerektirdi
// (Top_Unknown'da SS forward i5 %85.5 oraninda direkt eslesti).
const RC_INSTRUMENTS = [
  'Illumina NextSeq 1000',
  'Illumina NextSeq 2000',
  'Illumina NovaSeq X',
  'Illumina NovaSeq X Plus',
  'Illumina NovaSeq X-Plus',
  'Illumina iSeq 100',
];
const needsRC = RC_INSTRUMENTS.includes(instrumentModel);

// Reverse complement helper (UMI fix 2026-05-19)
function reverseComplement(seq) {
  if (!seq) return seq;
  const complement = { A: 'T', T: 'A', G: 'C', C: 'G', N: 'N' };
  return seq.toUpperCase().split('').reverse().map(b => complement[b] ?? b).join('');
}

const hasLanes = samples.some(sample => {
  const lane = sample.json.lane;
  return lane && lane !== 0 && lane !== '0' && lane !== '';
});

let sampleSheet = '[Header],\n';
sampleSheet += 'FileFormatVersion,2\n';
sampleSheet += `RunName,${runId}\n`;
sampleSheet += 'InstrumentPlatform,NovaSeqXSeries\n';
sampleSheet += 'IndexOrientation,Forward\n\n';
sampleSheet += '[Reads]\n';
sampleSheet += `Read1Cycles,${readsSettings.read1cycles}\n`;
sampleSheet += `Read2Cycles,${readsSettings.read2cycles}\n`;
sampleSheet += `Index1Cycles,${readsSettings.index1cycles}\n`;
sampleSheet += `Index2Cycles,${readsSettings.index2cycles}\n\n`;
sampleSheet += '[BCLConvert_Settings]\n';
sampleSheet += 'SoftwareVersion,4.3.13\n';
sampleSheet += 'AdapterRead1,CTGTCTCTTATACACATCT+AGATCGGAAGAGCACACGTCTGAACTCCAGTCA\n';
sampleSheet += 'AdapterRead2,CTGTCTCTTATACACATCT+AGATCGGAAGAGCGTCGTGTAGGGAAAGAGTGT\n';
sampleSheet += 'FastqCompressionFormat,gzip\n';
sampleSheet += '[BCLConvert_Data]\n';

if (hasLanes) {
  sampleSheet += 'Lane,Sample_ID,Index,Index2,OverrideCycles,Sample_Project,BarcodeMismatchesIndex1,BarcodeMismatchesIndex2\n';
} else {
  sampleSheet += 'Sample_ID,Index,Index2,OverrideCycles,Sample_Project,BarcodeMismatchesIndex1,BarcodeMismatchesIndex2\n';
}

for (const sample of samples) {
  const s = sample.json;

  const i5Sequence = needsRC ? reverseComplement(s.index2) : s.index2;

  const i7Length = s.index ? s.index.length : 0;
  const i5Length = i5Sequence ? i5Sequence.length : 0;

  const index1Cycles = parseInt(readsSettings.index1cycles);
  const index2Cycles = parseInt(readsSettings.index2cycles);

  let index1Part = '';
  if (i7Length === index1Cycles) {
    index1Part = `I${i7Length}`;
  } else {
    const mask1 = index1Cycles - i7Length;
    index1Part = `I${i7Length}N${mask1}`;
  }

  let index2Part = '';
  if (i5Length === index2Cycles) {
    index2Part = `I${i5Length}`;
  } else {
    const mask2 = index2Cycles - i5Length;
    // NextSeq 2000 / NovaSeq X / iSeq i5 ters yonden okur:
    // 10 cycle'lik i5 okumada 8bp gercek adapter cycle 3-10'da, ilk 2 cycle template/linker artigi.
    // Bu sequencer'lar icin mask N<n>I<i5> formatinda olmali (mask onde, indeks arkada).
    // NovaSeq 6000 v1.0 / MiSeq / HiSeq forward okur -> I<i5>N<n> (mevcut sira).
    // i7 her platformda forward; index1Part: I<n>N<m> dogru, dokunulmadi.
    index2Part = needsRC ? `N${mask2}I${i5Length}` : `I${i5Length}N${mask2}`;
  }

  // TSO500 (UMI) kit'leri için Read1/Read2 başında 7bp UMI + 1 mask:
  // Detect with normalized substring (whitespace/dash/underscore stripped).
  const libraryPrepKit = s.library_prep_kit || '';
  const normalizedKit = libraryPrepKit.toLowerCase().replace(/[\s\-_]/g, '');
  const isTSO = normalizedKit.includes('tso500') || normalizedKit.includes('trusightoncology500');
  const read1Part = isTSO ? `U7N1Y${parseInt(readsSettings.read1cycles) - 8}` : `Y${readsSettings.read1cycles}`;
  const read2Part = isTSO ? `U7N1Y${parseInt(readsSettings.read2cycles) - 8}` : `Y${readsSettings.read2cycles}`;
  const overrideCycles = `${read1Part};${index1Part};${index2Part};${read2Part}`;

  if (hasLanes) {
    const laneValue = (s.lane && s.lane !== 0 && s.lane !== '0') ? s.lane : '';
    sampleSheet += `${laneValue},${s.sample_id},${s.index},${i5Sequence},${overrideCycles},${s.sample_project},0,0\n`;
  } else {
    sampleSheet += `${s.sample_id},${s.index},${i5Sequence},${overrideCycles},${s.sample_project},0,0\n`;
  }
}

return {
  json: {
    sampleSheet: sampleSheet,
    fileName: `SampleSheet_${runId}.csv`,
    run_id: runId
  }
};
